import 'dart:io';import 'package:dotted_border/dotted_border.dart';import 'package:driver/utilitys/colors.dart';import 'package:driver/widgets/appButton.dart';import 'package:driver/widgets/app_inputs.dart';import 'package:flutter/material.dart';import 'package:image_picker/image_picker.dart';class CreateRestaurent extends StatefulWidget {  const CreateRestaurent({Key? key}) : super(key: key);  @override  State<CreateRestaurent> createState() => _CreateRestaurentState();}class _CreateRestaurentState extends State<CreateRestaurent> {  final _formKey = GlobalKey<FormState>();  final _name = TextEditingController();  final _email = TextEditingController();  final _phone = TextEditingController();  final _pass = TextEditingController();  final _location = TextEditingController();  bool _isLoading= false;  @override  Widget build(BuildContext context) {    return Scaffold(      backgroundColor: AppColors.bgColor,      appBar: AppBar(        backgroundColor: AppColors.bgColor,        leading: IconButton(          onPressed: ()=>Navigator.pop(context),          icon: Icon(Icons.arrow_back, color: Colors.black,),        ),        title: Text("Create Restaurent",style: TextStyle(fontWeight: FontWeight.w600, color: Colors.black),),      ),      body: SingleChildScrollView(        padding: EdgeInsets.all(15),        child: Form(          key: _formKey,          child: Column(            mainAxisAlignment: MainAxisAlignment.start,           crossAxisAlignment: CrossAxisAlignment.start,           children: [             AppInput(                 prefixIcon: Icon(Icons.search,color: Colors.grey,),                 title: "Restaurant Name",                 hintText: "Restaurant Name", controller: _name,                  validator: (value){                    if(value!.isEmpty){                      return "Please enter restaurant name";                    }                    return null;                  }             ),             SizedBox(height: 15,),             AppInput(                 prefixIcon: Icon(Icons.search,color: Colors.grey,),                 hintText: "Email", controller: _email,                 title:  "Email",                 validator: (value){                   if(value!.isEmpty){                     return "Please enter email";                   }                   return null;                 }             ),             SizedBox(height: 15,),             AppInput(                 prefixIcon: Icon(Icons.search,color: Colors.grey,),                 hintText: "Phone Number", controller: _email,                 title: "Phone Number",                 validator: (value){                   if(value!.isEmpty){                     return "Please enter Phone Number";                   }                   return null;                 }             ),             SizedBox(height: 15,),             AppInput(                 prefixIcon: Icon(Icons.search,color: Colors.grey,),                 hintText: "Password", controller: _pass,                 title: "Password",                 validator: (value){                   if(value!.isEmpty){                     return "Please enter password";                   }                   return null;                 }             ),             SizedBox(height: 15,),             AppInput(                 prefixIcon: Icon(Icons.search,color: Colors.grey,),                 hintText: "Restaurant Location", controller: _location,                 title:  "Restaurant Location",                 validator: (value){                   if(value!.isEmpty){                     return "Please enter email";                   }                   return null;                 }             ),             SizedBox(height: 15,),             Text("Logo Image",              style: TextStyle(                fontSize: 17,                fontWeight: FontWeight.w600,                color: Colors.black              ),             ),             SizedBox(height: 10,),             InkWell(                 onTap: ()=>_showBottomSheet(),                 child: DottedBorder(               borderType: BorderType.RRect,               radius: Radius.circular(12),               padding: EdgeInsets.all(6),               child: ClipRRect(                 borderRadius: BorderRadius.all(Radius.circular(12)),                 child: Container(                   height: 140,                   width: MediaQuery.of(context).size.width*0.45,                   color: Colors.white,                   child: Center(                     child: _image != null ? Image.file(_image!,) : Icon(Icons.add_a_photo_outlined, color: Colors.grey, size: 40,),                   )                 ),               ),             )),             SizedBox(height: 30,),             AppButton(text: "Create New", onClick: ()async{               setState(() => _isLoading = true);               await               setState(() => _isLoading = false);               ///TODO: Create new restaurant             }, width: 200, height: 60, isLoading: _isLoading,)           ]          ),        ),      ),    );  }  //show bottom sheet  _showBottomSheet() {    return showModalBottomSheet(        context: context,        builder: (context) {          return Padding(            padding: const EdgeInsets.all(20.0),            child: Column(              mainAxisSize: MainAxisSize.min,              mainAxisAlignment: MainAxisAlignment.start,              crossAxisAlignment: CrossAxisAlignment.start,              children: <Widget>[                SizedBox(height: 20,),                Text("Choose Photo",                  style: TextStyle(                    fontWeight: FontWeight.w600,                    fontSize: 20,                  ),                ),                SizedBox(height: 20,),                ListTile(                  leading: new Icon(Icons.camera_alt_outlined),                  title: new Text('Camera'),                  onTap: () {                    _takeImage(ImageSource.camera);                    Navigator.pop(context);                  },                ),                ListTile(                  leading: new Icon(Icons.photo_camera_back),                  title: new Text('Gallery'),                  onTap: () {                    _takeImage(ImageSource.gallery);                    Navigator.pop(context);                  },                ),              ],            ),          );        });  }  //take image  File? _image;  _takeImage(ImageSource source) async {    final picker = ImagePicker();    final pickedFile = await picker.pickImage(source: source);    print("pickedFile taken === ${File(pickedFile!.path)}");    if (pickedFile != null) {      setState(() {        _image = File(pickedFile.path);      });      //redirect to preview screen      //once you are get the image now this time to get 60 days from to day      print("image taken === ${File(pickedFile.path)}");    }  }}